import{_ as o,o as t,c as n,a3 as a}from"./chunks/framework.BTQ4eCVb.js";const u=JSON.parse('{"title":"Payments — Production Guide","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Payments — Production Guide | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/deployment/payments"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Payments — Production Guide | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/deployment/payments"}]]},"headers":[],"relativePath":"deployment/payments.md","filePath":"deployment/payments.md","lastUpdated":1788644779000}'),i={name:"deployment/payments.md"};function s(r,e,c,d,l,m){return t(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="payments-—-production-guide" tabindex="-1">Payments — Production Guide <a class="header-anchor" href="#payments-—-production-guide" aria-label="Permalink to &quot;Payments — Production Guide&quot;">​</a></h1><h2 id="licensing" tabindex="-1">Licensing <a class="header-anchor" href="#licensing" aria-label="Permalink to &quot;Licensing&quot;">​</a></h2><ul><li>Catalog slug: <code>payments</code></li><li>Category: <strong>Billing</strong> (<code>billing</code>)</li><li><strong>Free Marketplace opt-in</strong> (not auto-installed)</li><li>Catalog flags: <code>is_default_included = false</code>, <code>is_billable = false</code>, price <code>0</code>, <code>sort_order = 20</code></li><li><strong>Hard dependency on Invoices</strong> — declares a required <code>module_dependencies</code> row on <code>invoices</code>; Marketplace blocks installing Payments on a workspace that doesn&#39;t already have Invoices entitled</li></ul><h2 id="bootstrap" tabindex="-1">Bootstrap <a class="header-anchor" href="#bootstrap" aria-label="Permalink to &quot;Bootstrap&quot;">​</a></h2><p>On <strong>new workspace</strong> create:</p><ol><li><code>installDefaultModules()</code> installs published <code>is_default_included</code> modules only (Payments is never auto-installed)</li><li>Operators must enable <strong>Invoices</strong> before Payments becomes installable from Marketplace</li><li>Tenant permissions include <code>payments.*</code> via <code>config/tenant-permissions.php</code> / default role maps</li></ol><h2 id="permissions-rollout" tabindex="-1">Permissions rollout <a class="header-anchor" href="#permissions-rollout" aria-label="Permalink to &quot;Permissions rollout&quot;">​</a></h2><p>New Payments permissions for <strong>existing</strong> workspaces ship as an additive <strong>data migration</strong> using <code>TenantPermissionSynchronizer::grantMissingDefaultRolePermissions([...])</code> (see <code>database/migrations/2026_07_31_221005_add_payments_permissions.php</code>). Do <strong>not</strong> re-seed roles.</p><h2 id="monitoring" tabindex="-1">Monitoring <a class="header-anchor" href="#monitoring" aria-label="Permalink to &quot;Monitoring&quot;">​</a></h2><ul><li>Platform audit events: <code>customer_payment_created</code>, <code>customer_payment_updated</code>, <code>customer_payment_deleted</code>, <code>customer_payment_assigned</code>, <code>customer_payment_status_changed</code>, <code>customer_payment_note_added</code></li><li>Notifications: assignment via <code>CustomerPaymentAssignedNotification</code></li><li>Posting/voiding a payment updates linked <code>CustomerInvoice</code> balances synchronously in the same request — no queued job to monitor</li></ul><h2 id="deploy-checklist" tabindex="-1">Deploy checklist <a class="header-anchor" href="#deploy-checklist" aria-label="Permalink to &quot;Deploy checklist&quot;">​</a></h2><ol><li>Migrate tables (<code>customer_payments</code>, <code>customer_payment_allocations</code>, <code>customer_payment_notes</code>, <code>customer_payment_activities</code>)</li><li>Register the <code>payments</code> catalog module via migration (<code>DefaultModuleRegistrar</code>) as free Billing opt-in — <strong>not</strong> <code>db:seed</code></li><li>Run the <code>module_dependencies</code> migration that links <code>payments</code> → <code>invoices</code> (required)</li><li>Run the payments permissions migration so default roles receive missing <code>payments.*</code> grants</li><li>Confirm <code>module:payments</code> + <code>payments.*</code> permissions on target roles</li><li>Deploy Frontend SPA with Payments nav (Billing sidebar group, after Invoices) — verify a workspace <strong>without</strong> Invoices installed cannot install Payments from Marketplace</li><li>Verify posting a payment correctly advances the linked invoice(s) to <code>partial</code>/<code>paid</code>, and voiding reverses it, in a staging smoke test before rollout</li><li>Smoke <strong>posted</strong> payment: <strong>Download receipt</strong> PDF + <strong>Email receipt</strong> (<code>payments.send</code>) — draft/void must 422</li></ol>',12)])])}const g=o(i,[["render",s]]);export{u as __pageData,g as default};
